<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\Accessor\DcrInitialAccessTokenUsesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the DcrInitialAccessTokenUsesAccessor trait.
 *
 * Covers null default, string/VO assignment via withUses,
 * getUses/uses accessors, and isUsesChanged with/without original.
 */
class DcrInitialAccessTokenUsesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUses creates a new instance with the Uses set
     * from a string value, and getUses returns the primitive string.
     */
    public function testWithUsesFromString(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenUsesAccessorUnitTest();

        // Act
        $result = $holder->withUses(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getUses());
    }
    /**
     * Asserts that withuses has access to the value object
     * from a string value, and getUses returns the primitive string.
     */
    public function testWithUsesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenUsesAccessorUnitTest();

        // Act
        $result = $holder->withUses(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->uses()->value());
    }
    public function testChangedUses(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenUsesAccessorUnitTest()->withUses(1);
        $original = $holder->withUses(1);
        $same = $holder->withUses(1);
        $modified = $holder->withUses(2);

        // Act
        $withSame = $original->isUsesChanged($same);
        $withDiferent = $original->isUsesChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithDcrInitialAccessTokenUsesAccessorUnitTest
{
    use DcrInitialAccessTokenUsesAccessor;
}
